export const FOOD_IDS = { base: Object.keys(B), top: Object.keys(T), side: Object.keys(S) };
// a dish as the model describes it, cleaned: unknown ids drop out
export const picOf = v => {
    if (!v || typeof v !== 'object') return null;
    const base = B[String(v.base || '').trim()] ? String(v.base).trim() : '';
    if (!base) return null;
    const ids = (a, set, n) => (Array.isArray(a) ? a : []).map(x => String(x || '').trim()).filter(x => set[x]).slice(0, n);
    return { base, with: ids(v.with, T, 3), size: v.size === 'large' ? 'large' : 'regular', set: ids(v.set, S, 2) };
};
